#!/usr/bin/env python3
"""agent-bus 发消息。用法: agent_bus_send.py --to worker_ant --text "你好"

长文铁律：禁止静默砍尾。超长自动分片多条续发；也可用 --text-file 避免 shell 参数截断。
"""
from __future__ import annotations

import os
import argparse
import json
import sys
import urllib.error
import urllib.request
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
DC_PLATFORM_JSON = Path(
    os.environ.get(
        "DC_PLATFORM_JSON",
        str(SCRIPT_DIR.parent.parent / "dc-platform.json"),
    )
)
DEFAULT_AGENT = "youchu_ai"
BUS_PATH = "/api/v1/agent-bus/send"
# bus 单条建议上限：下游 TG 镜像 / 部分客户端曾按 ~3500 砍；超长主动分片
BUS_CHUNK_LEN = int(os.environ.get("AGENT_BUS_CHUNK_LEN", "3000"))

from agent_bus_state import (  # noqa: E402
    append_tg_status_event,
    mark_processed,
    mark_sent,
    record_outbound,
    resolve_active_thread,
    touch_ide_heartbeat,
    was_sent,
)

_CLOSE_KINDS = frozenset({"reply"})


def _split_bus_text(text: str, max_len: int = BUS_CHUNK_LEN) -> list[str]:
    if text is None:
        return [""]
    if max_len <= 0 or len(text) <= max_len:
        return [text]
    parts: list[str] = []
    rest = text
    while rest:
        if len(rest) <= max_len:
            parts.append(rest)
            break
        split_at = rest.rfind("\n", 0, max_len)
        if split_at <= 0:
            split_at = max_len
        parts.append(rest[:split_at])
        rest = rest[split_at:].lstrip("\n")
    if len(parts) <= 1:
        return parts
    n = len(parts)
    out = [parts[0] + f"\n\n（下续 1/{n}，共 {n} 段）"]
    for i, part in enumerate(parts[1:], start=2):
        out.append(f"（续 {i}/{n}）\n{part}")
    return out


def _outbound_id_from_result(result: dict) -> int:
    for key in ("id", "message_id", "bus_id"):
        raw = result.get(key)
        if raw is None:
            continue
        try:
            return int(raw)
        except (TypeError, ValueError):
            continue
    return 0


def _resolve_master_bus_id(from_agent: str, reply_to_bus_id: int | None) -> int:
    if reply_to_bus_id and reply_to_bus_id > 0:
        thread = resolve_active_thread(from_agent)
        if thread:
            mid = int(thread.get("master_id") or 0)
            if mid > 0:
                return mid
        return reply_to_bus_id
    thread = resolve_active_thread(from_agent)
    if thread:
        return int(thread.get("master_id") or 0)
    return 0


def _mirror_outbound_tg(
    from_agent: str,
    *,
    kind: str,
    text: str,
    reply_to_bus_id: int | None,
    result: dict | None,
    to_agent: str | None = None,
) -> None:
    """出站成功必写 TG 镜像（全文，由 tgbot 分片发送，禁止砍尾）。"""
    oid = _outbound_id_from_result(result or {})
    master_id = _resolve_master_bus_id(from_agent, reply_to_bus_id)
    ev: dict = {
        "type": kind,
        "channel": "agent_bus",
        "bus_id": master_id or (reply_to_bus_id or 0),
        "text": text,
    }
    if to_agent:
        ev["to_agent"] = to_agent.strip()
    if oid > 0:
        ev["outbound_id"] = oid
    if reply_to_bus_id and reply_to_bus_id > 0:
        ev["in_reply_to"] = reply_to_bus_id
    append_tg_status_event(from_agent, ev)
    if oid > 0:
        record_outbound(
            from_agent,
            outbound_id=oid,
            master_id=master_id,
            kind=kind,
            text=text,
        )


def _load_config() -> tuple[str, str]:
    if not DC_PLATFORM_JSON.is_file():
        raise SystemExit(f"缺少配置: {DC_PLATFORM_JSON}")
    data = json.loads(DC_PLATFORM_JSON.read_text(encoding="utf-8"))
    base = (data.get("base_url") or "").rstrip("/")
    token = (data.get("token") or "").strip()
    if not base or not token:
        raise SystemExit(f"{DC_PLATFORM_JSON} 需包含 base_url 与 token")
    return base, token


def _bind_outbound_local(
    *,
    from_agent: str,
    to_agent: str,
    text: str,
    reply_to_bus_id: int,
    kind: str,
) -> dict:
    """正文已发过（仅 fp）但未绑 bus_id 时，本地补绑状态，避免未结案重唤醒。"""
    mark_sent(from_agent, bus_id=reply_to_bus_id, text=text, kind=kind)
    hb_bus = reply_to_bus_id if reply_to_bus_id and reply_to_bus_id > 0 else _resolve_master_bus_id(
        from_agent, reply_to_bus_id,
    )
    if hb_bus > 0:
        touch_ide_heartbeat(from_agent, hb_bus)
    _mirror_outbound_tg(
        from_agent,
        kind=kind,
        text=text,
        reply_to_bus_id=reply_to_bus_id,
        result=None,
        to_agent=to_agent,
    )
    if kind in _CLOSE_KINDS and reply_to_bus_id and reply_to_bus_id > 0:
        mark_processed(from_agent, reply_to_bus_id)
        append_tg_status_event(
            from_agent,
            {
                "type": "done",
                "channel": "agent_bus",
                "bus_id": reply_to_bus_id,
            },
        )
    return {"ok": True, "skipped": True, "reason": "bound existing fp to bus"}


def _post_once(
    *,
    from_agent: str,
    to_agent: str,
    text: str,
    payload: dict,
    reply_to_bus_id: int | None,
) -> dict:
    base, token = _load_config()
    req_body: dict = {
        "from_agent": from_agent,
        "to_agent": to_agent,
        "text": text,
        "payload": payload,
    }
    if reply_to_bus_id and reply_to_bus_id > 0:
        req_body["reply_to_bus_id"] = reply_to_bus_id
    body = json.dumps(req_body, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        f"{base}{BUS_PATH}",
        data=body,
        method="POST",
        headers={
            "Content-Type": "application/json; charset=utf-8",
            "Authorization": f"Bearer {token}",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")[:500]
        raise SystemExit(f"HTTP {exc.code}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise SystemExit(f"请求失败: {exc}") from exc


def send(
    *,
    from_agent: str,
    to_agent: str,
    text: str,
    payload: dict | None = None,
    dedup: bool = True,
    reply_to_bus_id: int | None = None,
    kind: str = "reply",
) -> dict:
    if (
        dedup
        and reply_to_bus_id is not None
        and text
        and was_sent(from_agent, text=text, kind=kind)
        and not was_sent(from_agent, bus_id=reply_to_bus_id, kind=kind)
    ):
        return _bind_outbound_local(
            from_agent=from_agent,
            to_agent=to_agent,
            text=text,
            reply_to_bus_id=reply_to_bus_id,
            kind=kind,
        )
    if dedup and was_sent(from_agent, bus_id=reply_to_bus_id, text=text, kind=kind):
        return {"ok": True, "skipped": True, "reason": "duplicate outbound"}

    pl = dict(payload or {})
    if kind and "kind" not in pl:
        pl["kind"] = kind

    chunks = _split_bus_text(text)
    last_result: dict = {}
    for i, chunk in enumerate(chunks):
        # 仅首段带 reply_to 结案语义；续段同 kind 但不重复 mark
        chunk_kind = kind if i == 0 else ("progress" if kind == "reply" else kind)
        chunk_pl = dict(pl)
        chunk_pl["kind"] = chunk_kind
        if len(chunks) > 1:
            chunk_pl["chunk"] = {"i": i + 1, "n": len(chunks)}
        result = _post_once(
            from_agent=from_agent,
            to_agent=to_agent,
            text=chunk,
            payload=chunk_pl,
            reply_to_bus_id=reply_to_bus_id if i == 0 else None,
        )
        last_result = result
        if not result.get("ok"):
            return result
        if dedup and i == 0:
            mark_sent(from_agent, bus_id=reply_to_bus_id, text=text, kind=kind)
        hb_bus = (
            reply_to_bus_id
            if reply_to_bus_id and reply_to_bus_id > 0
            else _resolve_master_bus_id(from_agent, reply_to_bus_id)
        )
        if hb_bus > 0:
            touch_ide_heartbeat(from_agent, hb_bus)
        _mirror_outbound_tg(
            from_agent,
            kind=chunk_kind,
            text=chunk,
            reply_to_bus_id=reply_to_bus_id if i == 0 else None,
            result=result,
            to_agent=to_agent,
        )

    if kind in _CLOSE_KINDS and reply_to_bus_id and reply_to_bus_id > 0:
        mark_processed(from_agent, reply_to_bus_id)
        append_tg_status_event(
            from_agent,
            {
                "type": "done",
                "channel": "agent_bus",
                "bus_id": reply_to_bus_id,
            },
        )
    if len(chunks) > 1:
        last_result = dict(last_result)
        last_result["chunks"] = len(chunks)
    return last_result


def main() -> None:
    p = argparse.ArgumentParser(description="agent-bus 发消息")
    p.add_argument("--from", dest="from_agent", default=DEFAULT_AGENT, help=f"发送方 agent 名（默认 {DEFAULT_AGENT}）")
    p.add_argument("--to", required=True, help="接收方 agent 名，或 all 广播")
    p.add_argument("--text", default=None, help="消息正文（与 --text-file 二选一）")
    p.add_argument("--text-file", default=None, help="从文件读正文（长文推荐，防 shell 截断）")
    p.add_argument("--payload", default="{}", help="JSON payload（默认 {}）")
    p.add_argument("--reply-to-bus-id", type=int, default=None, help="入站 bus id（出站去重）")
    p.add_argument("--no-dedup", action="store_true", help="跳过去重（强制重发）")
    p.add_argument("--kind", default="reply", help="出站类型 ack/reply/progress（progress=阶段同步不结案）")
    p.add_argument("--no-chunk", action="store_true", help="禁止自动分片（仅调试；超长仍可能被下游砍）")
    args = p.parse_args()
    if args.text_file:
        text = Path(args.text_file).read_text(encoding="utf-8")
    elif args.text is not None:
        text = args.text
    else:
        raise SystemExit("必须提供 --text 或 --text-file")
    try:
        payload = json.loads(args.payload)
    except json.JSONDecodeError as exc:
        raise SystemExit(f"--payload 不是合法 JSON: {exc}") from exc
    global BUS_CHUNK_LEN
    if args.no_chunk:
        BUS_CHUNK_LEN = 10**9
    result = send(
        from_agent=args.from_agent,
        to_agent=args.to,
        text=text,
        payload=payload,
        dedup=not args.no_dedup,
        reply_to_bus_id=args.reply_to_bus_id,
        kind=args.kind,
    )
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

